Here's an example Swift function that takes in a string parameter in first-person point of view and returns the same statement in third-person point of view:
```
func rephraseToThirdPerson(_ statement: String) -> String {
    let words = statement.split(separator: " ")
    var newWords = [String]()

    for word in words {
        if word.lowercased() == "i" {
            newWords.append("They")
        } else if word.lowercased() == "me" {
            newWords.append("them")
        } else {
            newWords.append(String(word))
        }
    }

    return newWords.joined(separator: " ")
}
```
