To calculate the nutritional value of a recipe in C++, you can create a class called "Ingredient" that contains the name, serving size, and nutritional information of each ingredient. Then, you can create a class called "Recipe" that contains a list of ingredients and their respective amounts.
Here's an example implementation:
```c++
#include <iostream>
#include <vector>
#include <string>
using namespace std;
class Ingredient {
public:
    string name;
    double serving_size;
    double calories;
    double total_fat;
    double saturated_fat;
    double cholesterol;
    double sodium;
    double total_carbohydrate;
    double dietary_fiber;
    double total_sugars;
    double protein;
};
class Recipe {
public:
    vector<pair<Ingredient, double>> ingredients; // pair of ingredient and amount
    void addIngredient(Ingredient ingredient, double amount) {
        ingredients.push_back(make_pair(ingredient, amount));
    }
    void printNutrition() {
        double total_calories = 0;
        double total_fat = 0;
        double total_saturated_fat = 0;
        double total_cholesterol = 0;
        double total_sodium = 0;
        double total_carbohydrate = 0;
        double total_dietary_fiber = 0;
        double total_sugars = 0;
        double total_protein = 0;
        for (auto i : ingredients) {
            Ingredient ingredient = i.first;
            double amount = i.second;
            total_calories += (ingredient.calories / ingredient.serving_size) * amount;
            total_fat += (ingredient.total_fat / ingredient.serving_size) * amount;
            total_saturated_fat += (ingredient.saturated_fat / ingredient.serving_size) * amount;
            total_cholesterol += (ingredient.cholesterol / ingredient.serving_size) * amount;
            total_sodium += (ingredient.sodium / ingredient.serving_size) * amount;
            total_carbohydrate += (ingredient.total_carbohydrate / ingredient.serving_size) * amount;
            total_dietary_fiber += (ingredient.dietary_fiber / ingredient.serving_size) * amount;
            total_sugars += (ingredient.total_sugars / ingredient.serving_size) * amount;
            total_protein += (ingredient.protein / ingredient.serving_size) * amount;
        }
        cout << "[Nutritional Information]:" << endl;
        cout << "| Nutrient | Amount per serving |" << endl;
        cout << "| -------- | ----------------- |" << endl;
        cout << "| Calories | " << total_calories << " |" << endl;
        cout << "| Total Fat | " << total_fat << " g |" << endl;
        cout << "| Saturated Fat | " << total_saturated_fat << " g |" << endl;
        cout << "| Cholesterol | " << total_cholesterol << " mg |" << endl;
        cout << "| Sodium | " << total_sodium << " mg |" << endl;
        cout << "| Total Carbohydrate | " << total_carbohydrate << " g |" << endl;
        cout << "| Dietary Fiber | " << total_dietary_fiber << " g |" << endl;
        cout << "| Total Sugars | " << total_sugars << " g |" << endl;
        cout << "| Protein | " << total_protein << " g |" << endl;
    }
};
int main() {
    Ingredient flour = {"Flour", 1, 455, 1.2, 0.2, 0, 1, 95.4, 3.4, 0.1, 12.9};
    Ingredient sugar = {"Sugar", 1, 387, 0, 0, 0, 1, 100, 0, 100, 0};
    Ingredient baking_powder = {"Baking Powder", 1, 2, 0, 0, 0, 488, 0.7, 0, 0.7, 0};
    Ingredient salt = {"Salt", 1, 0, 0, 0, 0, 38758, 0, 0, 0, 0};
    Ingredient milk = {"Milk", 1, 42, 1, 0.6, 5, 44, 5.2, 0, 5.2, 3.4};
    Ingredient egg = {"Egg", 1, 78, 5.3, 1.6, 186, 63, 0.6, 0, 0.6, 6.3};
    Ingredient butter = {"Butter", 1, 717, 81.1, 51.4, 215, 714, 0, 0, 0, 0.9};
    Recipe recipe;
    recipe.addIngredient(flour, 1);
    recipe.addIngredient(sugar, 1);
    recipe.addIngredient(baking_powder, 2);
    recipe.addIngredient(salt, 0.75);
    recipe.addIngredient(milk, 1);
    recipe.addIngredient(egg, 1);
    recipe.addIngredient(butter, 2);
    recipe.printNutrition();
    return 0;
}
```
