#include <vector>
using namespace std;
bool isBanned(string word, vector<string> bannedWords) {
    for (string bannedWord : bannedWords) {
        if (word == bannedWord) {
            return true;
        }
    }
    return false;
}
int main()
{
    srand(time(NULL)); // Initialize random seed

    string letters = "abcdefghijklmnopqrstuvwxyz"; // Define the pool of letters to choose from
