    vector<string> bannedWords = {"hate", "kill", "evil", "raci", "sexu"}; // Define a list of banned words

    do {
        word = "";
        for (int i = 0; i < 4; i++) {
            int index = rand() % letters.length(); // Generate a random index within the length of the letters string
            word += letters[index]; // Append the randomly selected letter to the word
        }
    } while (isBanned(word, bannedWords)); // Keep generating words until a non-banned word is found

    cout << "Your unique four-letter word for friendship is: " << word << endl;

    return 0;
}
```
Note that this is just an example implementation, and you may want to customize the list of banned words and the algorithm for generating the unique word to suit your specific needs.

