```
#include <iostream>
#include <string>
#include <vector>
// Define positive and negative words
std::vector<std::string> positive_words = {"good", "great", "excellent"};
std::vector<std::string> negative_words = {"bad", "poor", "disappointment"};
// Function to calculate sentiment score
int calculate_sentiment_score(std::string review) {
    int score = 0;
    for (auto& word : positive_words) {
        if (review.find(word) != std::string::npos) {
            score++;
        }
    }
    for (auto& word : negative_words) {
        if (review.find(word) != std::string::npos) {
            score--;
        }
    }
    return score;
}
int main() {
    // Get customer review from JSON data
    std::string customer_review = "This product is a total disappointment";
    // Calculate sentiment score
    int sentiment_score = calculate_sentiment_score(customer_review);
    // Print sentiment analysis result
    if (sentiment_score > 0) {
        std::cout << "Positive" << std::endl;
    } else if (sentiment_score < 0) {
        std::cout << "Negative" << std::endl;
    } else {
        std::cout << "Neutral" << std::endl;
    }
    return 0;
}
